    if (!config.frameStrokeWidth || !config.svgId) return;
    insetsGroup.select('#em-inset-' + config.svgId + ' .em-frame').classed('em-inset-detail-frame', true).style('stroke', null).style('stroke-width', config.frameStrokeWidth + 'px', 'important');
